// ---- Generic Table Page ----
const TablePage = ({ title, fetchUrl, columns }) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get(fetchUrl)
      .then(r => setData(Object.values(r.data).find(v => Array.isArray(v)) || []))
      .catch(() => setData([]))
      .finally(() => setLoading(false));
  }, [fetchUrl]);

  return (
    <div className="page-content">
      <h1 className="page-title">{title}</h1>
      {loading ? (
        <div className="loading-state">Đang tải dữ liệu...</div>
      ) : (
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>{columns.map(c => <th key={c.key}>{c.label}</th>)}</tr>
            </thead>
            <tbody>
              {data.length === 0 ? (
                <tr><td colSpan={columns.length} className="empty-row">Chưa có dữ liệu</td></tr>
              ) : data.map((row, i) => (
                <tr key={row.id || i}>
                  {columns.map(c => (
                    <td key={c.key}>
                      {c.render ? c.render(row[c.key], row) : (row[c.key] ?? '—')}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

const RoleBadge = (role) => {
  const map = { admin: '#c0392b', teacher: '#1565C0', student: '#2d7a3a' };
  const label = { admin: 'Admin', teacher: 'Giáo viên', student: 'Học viên' };
  return <span className="badge" style={{background: map[role] || '#888'}}>{label[role] || role}</span>;
};

const StatusBadge = (val) => (
  <span className="badge" style={{background: val ? '#2d7a3a' : '#999'}}>
    {val ? 'Hoạt động' : 'Đã khóa'}
  </span>
);

// ---- Register ----
const RegisterPage = () => {
  const [form, setForm] = useState({ username:'', password:'', full_name:'', role:'student', email:'' });
  const [msg, setMsg] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true); setMsg(null);
    try {
      await axios.post(`${API}/admin/users`, form);
      setMsg({ type: 'success', text: 'Tạo tài khoản thành công!' });
      setForm({ username:'', password:'', full_name:'', role:'student', email:'' });
    } catch(err) {
      setMsg({ type: 'error', text: err.response?.data?.message || 'Lỗi tạo tài khoản' });
    } finally { setLoading(false); }
  };

  return (
    <div className="page-content">
      <h1 className="page-title">Đăng kí tài khoản</h1>
      <div className="form-card">
        {msg && <div className={`form-msg ${msg.type}`}>{msg.text}</div>}
        <form onSubmit={handleSubmit} className="form-grid">
          <div className="form-group">
            <label>Tên tài khoản *</label>
            <input value={form.username} onChange={e=>setForm({...form,username:e.target.value})} required placeholder="Nhập username"/>
          </div>
          <div className="form-group">
            <label>Mật khẩu *</label>
            <input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} required placeholder="Nhập mật khẩu"/>
          </div>
          <div className="form-group">
            <label>Họ và tên *</label>
            <input value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})} required placeholder="Nhập họ tên"/>
          </div>
          <div className="form-group">
            <label>Email</label>
            <input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="Nhập email"/>
          </div>
          <div className="form-group">
            <label>Vai trò</label>
            <select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>
              <option value="student">Học viên</option>
              <option value="teacher">Giáo viên</option>
              <option value="admin">Admin</option>
            </select>
          </div>
          <div className="form-group full-width">
            <button type="submit" className="submit-btn" disabled={loading}>
              {loading ? 'Đang tạo...' : 'Tạo tài khoản'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

